Here is an implementation of a recursive binary search in Python for the list `[-4, -2, 0, 6, 7, 8]`:

```python
def recursive_binary_search(arr, target, left, right):
    # Base case: if the search space is invalid, the element is not found
    if left > right:
        return -1

    # Calculate the middle index
    mid = (left + right) // 2

    # Check if the middle element is the target
    if arr[mid] == target:
        return mid
    # If the target is smaller, search in the left half
    elif arr[mid] > target:
        return recursive_binary_search(arr, target, left, mid - 1)
    # If the target is larger, search in the right half
    else:
        return recursive_binary_search(arr, target, mid + 1, right)

# Example usage
data = [-4, -2, 0, 6, 7, 8]
target = 6
index = recursive_binary_search(data, target, 0, len(data) - 1)

if index != -1:
    print(f"Element {target} found at index {index}.")
else:
    print(f"Element {target} not found.")
```

